function transform(nums)
  local doubled = {}
  for i, v in ipairs(nums) do doubled[i] = v * 2 end
  local out = {}
  for _, v in ipairs(doubled) do
    if v >= 10 then out[#out + 1] = v end
  end
  return out
end

